<script setup lang="ts">
import { computed, onBeforeUnmount, ref, shallowRef, watch } from 'vue'
import CharacterFormFields,{type CharacterFields} from './CharacterFormFields.vue'
import PortraitCropEditor from './PortraitCropEditor.vue'
import { get,mutate } from '../api/client'
import { legacyNames,multilingualDisplay } from '../utils/multilingualNames'
import type { CharacterNode } from '../types/characterGraph'
import type { CharacterCrop,CharacterEdit } from '../types/characterEdit'
import type { LocalName } from '../types/localGraph'
const props=defineProps<{node:CharacterNode;workUid?:string;initialOpen?:boolean}>()
const emit=defineEmits<{saved:[]}>()
const open=shallowRef(!!props.initialOpen),saved=shallowRef<CharacterEdit>(),draft=ref<CharacterFields>({names:[],preferredNameId:null,imageUrl:'',gender:'',description:'',notes:''}),crop=shallowRef<CharacterCrop|null>(null),cropScope=shallowRef('GLOBAL'),error=shallowRef(''),message=shallowRef(''),busy=shallowRef(false),baseline=shallowRef(''),sourceVersion=shallowRef('')
const backups=shallowRef<{id:string;version:number;createdAt:string}[]>([])
const original=computed(()=>props.node.sourceOriginal||props.node)
const endpoint=computed(()=>'/character-edits/'+encodeURIComponent(props.node.id))
const dirty=computed(()=>!!saved.value&&baseline.value!==JSON.stringify({draft:draft.value,crop:crop.value,scope:cropScope.value}))
const fields=['names','imageUrl','gender','description','notes'] as const
function originalNames():LocalName[]{const n=original.value;if(n.nameAssertions?.length)return n.nameAssertions.map((a,i)=>({id:'source-'+i,text:a.name,locale:a.locale||'und',kind:(a.kind==='ORIGINAL'?'ORIGINAL':'ALIAS') as LocalName['kind'],source:a.provider,reviewStatus:a.reviewStatus})).filter((v,i,all)=>all.findIndex(n=>n.text===v.text&&n.locale===v.locale)===i);return legacyNames(n.label,[...(n.aliases||[]),...(n.originalName?[n.originalName]:[])])}
function sourceDraft():CharacterFields{return {names:originalNames(),preferredNameId:null,imageUrl:original.value.imageUrl||'',gender:original.value.gender||'',description:original.value.description||'',notes:original.value.notes||''}}
function signature(){return JSON.stringify({draft:draft.value,crop:crop.value,scope:cropScope.value})}
async function load(){const owner=endpoint.value;busy.value=true;error.value='';try{const data=await get<CharacterEdit>(owner);if(owner!==endpoint.value)return;saved.value=data;draft.value={...sourceDraft(),...data.fields};crop.value=data.portraits[cropScope.value]||null;if(crop.value?.imageUrl)draft.value.imageUrl=crop.value.imageUrl;baseline.value=signature();const pending=sessionStorage.getItem('character-draft:'+props.node.id);if(pending){try{const recovered=JSON.parse(pending);draft.value=recovered.draft;crop.value=recovered.crop;cropScope.value=recovered.scope;saved.value={...data,version:recovered.version};message.value='已恢复该角色未保存草稿，请核对后保存。'}catch{}}const hash=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(sourceDraft())));if(owner!==endpoint.value)return;sourceVersion.value=Array.from(new Uint8Array(hash)).map(v=>v.toString(16).padStart(2,'0')).join('');if(data.sourceVersion&&data.sourceVersion!==sourceVersion.value)message.value='来源资料自上次修改后发生变化，本地修改已保留，请逐字段核对。';backups.value=await get(endpoint.value+'/backups')}catch(cause){if(owner===endpoint.value)error.value=cause instanceof Error?cause.message:'读取角色修改失败'}finally{if(owner===endpoint.value)busy.value=false}}
function restoreField(field:typeof fields[number]){const source=sourceDraft();if(field==='names'){draft.value.names=source.names;draft.value.preferredNameId=null}else draft.value[field]=source[field]}
function download(value:unknown,name:string){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function save(reset=false){if(!saved.value||busy.value)return;const owner=endpoint.value;busy.value=true;error.value='';try{const changes:Record<string,unknown>={};const source=sourceDraft();if(!reset){for(const field of fields)if(JSON.stringify(draft.value[field])!==JSON.stringify(source[field]))changes[field]=draft.value[field];if(changes.names)changes.preferredNameId=draft.value.preferredNameId;else if(draft.value.preferredNameId){changes.names=draft.value.names;changes.preferredNameId=draft.value.preferredNameId}}
const portraits=reset?{}:{...saved.value.portraits};if(!reset){if(crop.value){if(cropScope.value==='GLOBAL'){const setting={...crop.value};delete setting.imageUrl;portraits.GLOBAL=setting;changes.imageUrl=draft.value.imageUrl;}else portraits[cropScope.value]={...crop.value,imageUrl:draft.value.imageUrl};}else delete portraits[cropScope.value]}
if(!reset&&cropScope.value!=='GLOBAL'){if(!crop.value&&draft.value.imageUrl!==String(saved.value.fields.imageUrl??sourceDraft().imageUrl))throw new Error('本作头像需读取图片内容后才能保存，请等待图片加载并调整取景。');delete changes.imageUrl;if(saved.value.fields.imageUrl!==undefined)changes.imageUrl=saved.value.fields.imageUrl;}
await mutate<CharacterEdit>(owner,'PUT',{...saved.value,sourceVersion:sourceVersion.value,fields:changes,portraits});if(owner!==endpoint.value)return;sessionStorage.removeItem('character-draft:'+props.node.id);baseline.value=signature();message.value=reset?'已恢复全部来源资料与自动取景':'已保存，当前服务实例的角色资料已更新';emit('saved');busy.value=false;await load()}catch(cause){if(owner===endpoint.value)error.value=cause instanceof Error?cause.message:'保存失败'}finally{if(owner===endpoint.value)busy.value=false}}
async function importBackup(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file||!saved.value)return;try{if(file.size>1024*1024)throw new Error('角色备份不得超过1MB');const data=JSON.parse(await file.text()) as CharacterEdit;if(data.uid!==props.node.id||data.schemaVersion!==1)throw new Error('请选择当前角色的独立修改备份');draft.value={...sourceDraft(),...data.fields};saved.value={...saved.value,portraits:data.portraits};crop.value=data.portraits[cropScope.value]||null;message.value='备份已载入草稿，点击保存后生效。'}catch(cause){error.value=cause instanceof Error?cause.message:'备份读取失败'}}
async function restoreBackup(id:string){try{const data=await get<CharacterEdit>(endpoint.value+'/backups/'+id);if(!saved.value)return;draft.value={...sourceDraft(),...data.fields};saved.value={...saved.value,portraits:data.portraits};crop.value=data.portraits[cropScope.value]||null;message.value='历史版本已载入草稿，点击保存后生效。'}catch(cause){error.value=cause instanceof Error?cause.message:'备份读取失败'}}
watch(()=>props.node.id,()=>{saved.value=undefined;error.value='';message.value='';open.value=!!props.initialOpen;if(open.value)void load()},{immediate:true})
watch(open,value=>{if(value&&!saved.value)void load()})
watch(cropScope,(scope,previous)=>{if(saved.value){if(crop.value)saved.value={...saved.value,portraits:{...saved.value.portraits,[previous]:previous==='GLOBAL'?crop.value:{...crop.value,imageUrl:draft.value.imageUrl}}};if(previous==='GLOBAL'&&draft.value.imageUrl!==String(saved.value.fields.imageUrl??sourceDraft().imageUrl))saved.value={...saved.value,fields:{...saved.value.fields,imageUrl:draft.value.imageUrl}};crop.value=saved.value.portraits[scope]||null;draft.value.imageUrl=crop.value?.imageUrl||String(saved.value.fields.imageUrl??sourceDraft().imageUrl)}})
function unload(event:BeforeUnloadEvent){if(dirty.value){event.preventDefault();event.returnValue=''}}
window.addEventListener('beforeunload',unload);onBeforeUnmount(()=>{window.removeEventListener('beforeunload',unload);if(dirty.value)try{sessionStorage.setItem('character-draft:'+props.node.id,JSON.stringify({draft:draft.value,crop:crop.value,scope:cropScope.value,version:saved.value?.version}))}catch{}})
function close(){if(dirty.value&&!window.confirm('放弃未保存的角色草稿？可先导出草稿。'))return;open.value=false;saved.value=undefined}
</script>
<template><section v-if="/^character:bangumi:/.test(node.id)" class="source-editor"><button v-if="!open" type="button" @click="open=true">编辑角色</button><div v-else class="character-edit-form"><div class="edit-heading"><h3>编辑 {{ node.label }}</h3><button type="button" @click="close">关闭表单</button></div><p>修改由当前服务实例共享，保留来源身份与关系，不上传 Bangumi。原始资料可逐字段恢复；角色修改与作品备份独立保存。</p><p v-if="error" role="alert">{{ error }} <button v-if="saved" type="button" @click="download({...saved,fields:draft},'角色修改草稿')">导出当前草稿</button></p><p v-if="message" role="status">{{ message }}</p><form v-if="saved" @submit.prevent="save()"><CharacterFormFields v-model="draft"/><p>显示预览：{{ multilingualDisplay(draft.names||[],draft.preferredNameId) }}</p><div class="restore-fields"><button v-for="field in fields" :key="field" type="button" @click="restoreField(field)">恢复{{ ({names:'来源名称',imageUrl:'来源头像',gender:'来源性别',description:'来源简介',notes:'来源备注'})[field] }}</button></div><label>取景作用范围<select v-model="cropScope"><option value="GLOBAL">角色通用取景</option><option v-if="workUid" :value="workUid">仅当前作品</option></select></label><PortraitCropEditor v-model="crop" :uid="node.id" :url="draft.imageUrl"/><div class="edit-actions"><button class="primary" :disabled="busy">保存角色修改</button><button type="button" :disabled="busy" @click="save(true)">恢复全部来源</button><button type="button" @click="download(saved,'角色修改-'+node.id.split(':').at(-1))">导出独立备份</button></div><label>载入本角色独立备份<input type="file" accept="application/json,.json" @change="importBackup"></label><details v-if="backups.length"><summary>自动备份（最近20份）</summary><button v-for="backup in backups" :key="backup.id" type="button" @click="restoreBackup(backup.id)">版本 {{ backup.version }} · {{ new Date(backup.createdAt).toLocaleString('zh-CN') }}</button></details><details><summary>核对原始来源资料</summary><p>{{ original.label }} · {{ original.originalName }}</p><p>{{ original.description||'来源未提供简介' }}</p></details><p v-if="dirty" role="status">有未保存的修改。</p></form></div></section></template>
<style scoped>.source-editor{font-size:12px;margin:12px 0}.character-edit-form{padding:20px;background:var(--panel,#f3f8f4);border:1px solid #cddfd2;border-radius:12px;max-width:760px}.edit-heading{display:flex;gap:12px;align-items:center;justify-content:space-between}.edit-heading h3{margin:0;font-size:19px}.character-edit-form p{line-height:1.9;overflow-wrap:anywhere}.character-edit-form form{display:grid;gap:16px}.edit-actions,.restore-fields{display:flex;gap:8px;flex-wrap:wrap}.source-editor button{font-size:12px;min-height:36px}.source-editor label{font-size:12px}.source-editor details button{display:block;margin:8px 0}.source-editor summary{cursor:pointer;min-height:35px}@media(prefers-color-scheme:dark){.character-edit-form{background:#21382c;color:#d9e7de}}</style>
